hooks.command:
python -c "
import sys, json
data = json.load(sys.stdin)
cmd = data.get('tool_input', {}).get('command', '').lower()
protected = ['expense_tracker.db', '.env', 'migrations/']
dangerous = ['rm ', 'rm -', 'del ', 'erase ', 'remove-item', 'ri ', 'unlink', 'truncate', 'clear-content', 'move-item', 'mv ']
for d in dangerous:
    if d in cmd:
        for p in protected:
            if p in cmd:
                print(f'BLOCKED: Cannot run destructive command on protected file: {p}', file=sys.stderr)
                raise SystemExit(2)
"
